  ('e2000000-0000-4000-a000-00000000083a', 'ENEM-2020-086', 8, 418, 'enem', 3, 2, 2020, 'multiple_choice', 'Idade Moderna', 'Declaração de Direitos do Homem e do Cidadão — 1789

