  ('e2000000-0000-4000-b000-000000004f82', 'e2000000-0000-4000-a000-0000000007f3', 4, 'Possui jogadores e jogadoras com a mesma visibilidade, apesar de haver expoentes feministas de destaque, como Marta.', false),
