  ('e2000000-0000-4000-b000-000000004f94', 'e2000000-0000-4000-a000-0000000007f5', 2, 'Reforça a necessidade de solucionar os problemas de saúde da sociedade com a prática de exercícios.', false),
  ('e2000000-0000-4000-b000-000000004f95', 'e2000000-0000-4000-a000-0000000007f5', 3, 'Problematiza a organização social e seu impacto na mudança de hábitos dos indivíduos.', true),
  ('e2000000-0000-4000-b000-000000004f96', 'e2000000-0000-4000-a000-0000000007f5', 4, 'Reproduz a noção de que a melhoria da aptidão física pela prática de exercícios promove a saúde.', false),
  ('e2000000-0000-4000-b000-000000004f9c', 'e2000000-0000-4000-a000-0000000007f6', 0, 'Desvela sentimentos de vazio e angústia sob a aparente austeridade.', true),
