  ('e2000000-0000-4000-b000-000000004fba', 'e2000000-0000-4000-a000-0000000007f9', 0, 'Valorização do teatro, música, artesanato, literatura, dança, personagens históricos e artistas populares, compondo um tecido diversificado e enriquecedor da cultura popular como patrimônio regional e nacional.', false),
  ('e2000000-0000-4000-b000-000000004fbb', 'e2000000-0000-4000-a000-0000000007f9', 1, 'Identificação dos lugares pernambucanos, manifestações culturais, como o bumba meu boi, as cirandas, os bonecos mamulengos e heróis locais, fazendo com que essa canção se apresente como uma referência à cultura popular nordestina.', true),
  ('e2000000-0000-4000-b000-000000004fbc', 'e2000000-0000-4000-a000-0000000007f9', 2, 'Exaltação das raízes populares, como a poesia, a literatura de cordel e o frevo, misturadas ao erudito, como a Orquestra Armorial, compondo um rico tecido cultural, que transforma o popular em erudito.', false),
  ('e2000000-0000-4000-b000-000000004fbd', 'e2000000-0000-4000-a000-0000000007f9', 3, 'Caracterização das festas populares como identidade cultural localizada e como representantes de uma cultura que reflete valores históricos e sociais próprios da população local.', false),
  ('e2000000-0000-4000-b000-000000004fbe', 'e2000000-0000-4000-a000-0000000007f9', 4, 'Apresentação do Pastoril do Faceta, do maracatu, do bumba meu boi e dos autos como representação da musicalidade e do teatro popular religioso, bastante comum ao folclore brasileiro.', false),
  ('e2000000-0000-4000-b000-000000004fc4', 'e2000000-0000-4000-a000-0000000007fa', 0, 'Promover ações de conscientização para reduzir a violência de gênero em eventos esportivos.', true),
