  ('e2000000-0000-4000-b000-000000005002', 'e2000000-0000-4000-a000-000000000800', 2, 'Necessidade de divulgar a música de concerto nos meios populares nas periferias das grandes cidades', false),
  ('e2000000-0000-4000-b000-000000005003', 'e2000000-0000-4000-a000-000000000800', 3, 'Utilização desintencional de uma música excessivamente distante da realidade cultural dos jovens brasileiros', false),
  ('e2000000-0000-4000-b000-000000005004', 'e2000000-0000-4000-a000-000000000800', 4, 'Inter-relação de elementos culturais vindos de realidades distintas na construção de uma nova proposta musical", dizia a questão.', true),
